CREATE TABLE IF NOT EXISTS form_delivery_nonces (nonce TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lead_delivery_status (environment TEXT NOT NULL, client_id TEXT NOT NULL, submission_id TEXT NOT NULL, correlation_id TEXT NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL, provider_message_id TEXT, error_classification TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, submission_id));
CREATE TABLE IF NOT EXISTS provider_delivery_events (environment TEXT NOT NULL, client_id TEXT NOT NULL, provider TEXT NOT NULL, provider_message_id TEXT NOT NULL, event_type TEXT NOT NULL, correlation_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (environment, provider, provider_message_id, event_type));
CREATE TABLE IF NOT EXISTS delivery_suppression (environment TEXT NOT NULL, client_id TEXT NOT NULL, suppression_ref TEXT NOT NULL, channel TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (environment, client_id, suppression_ref, channel));
